mapper.select:
select samples.sample_type as sampleType, samples.stock_code as stockCode, samples.market as market,
       samples.event_trade_date as eventTradeDate, samples.anchor_at as anchorAt, samples.event_type as eventType,
       samples.matching_metadata as matchingMetadata, samples.source as source, samples.coverage as coverage
  from cynexus_appl_market.market_factor_study_sample samples
  join cynexus_appl_market.market_factor_study studies on studies.id=samples.study_id
 where studies.tenant_id=#{tenantId} and studies.owner_id=#{ownerId} and studies.study_code=#{studyCode}
   and studies.deleted_at is null
and samples.sample_type=#{sampleType}
 order by samples.event_trade_date asc, samples.stock_code asc
 offset #{offset} limit #{limit}

select samples.id from cynexus_appl_market.market_factor_study_sample samples
 where samples.study_id=#{studyId} and samples.sample_type=#{sampleType} and samples.stock_code=#{code}
   and samples.market=#{market} and samples.event_trade_date=#{eventTradeDate}

mapper.insert:
insert into cynexus_appl_market.market_factor_study_sequence_snapshot (id, study_id, study_sample_id, frequency, sequence_code, offset_value, observed_at, available_at, raw_value, normalized_value, source) select values_row.id, #{studyId}, samples.id, values_row.frequency, values_row.sequence_code, values_row.offset_value, values_row.observed_at, values_row.available_at, values_row.raw_value, values_row.normalized_value, cast(values_row.source as jsonb) from (values
(#{point.id}, #{point.sampleType}, #{point.code}, #{point.market}, #{point.eventTradeDate}, #{point.frequency}, #{point.sequenceCode}, #{point.offsetValue}, #{point.observedAt}, #{point.availableAt}, #{point.rawValue}, #{point.normalizedValue}, #{point.source})
) as values_row(id, sample_type, code, market, event_trade_date, frequency, sequence_code, offset_value, observed_at, available_at, raw_value, normalized_value, source) join cynexus_appl_market.market_factor_study_sample samples on samples.study_id=#{studyId} and samples.sample_type=values_row.sample_type and samples.stock_code=values_row.code and samples.market=values_row.market and samples.event_trade_date=values_row.event_trade_date on conflict (study_sample_id, frequency, sequence_code, offset_value) do nothing

mapper.select:
select snapshots.trade_date as featureTradeDate, snapshots.close,
       appetite.hs300_close as benchmarkClose
  from cynexus_appl_market.a_stock_daily_factor_snapshot snapshots
  left join cynexus_appl_market.msi_risk_appetite_daily appetite on appetite.trade_date=snapshots.trade_date
 where snapshots.code=#{code} and snapshots.market=#{market} and snapshots.trade_date >= #{eventDate}
   and snapshots.available_at <= #{dataCutoffAt} and snapshots.feature_version=#{featureVersion}
 order by snapshots.trade_date asc
 limit #{sessions}

mapper.update:
update cynexus_appl_market.market_factor_study_sample
   set outcome_snapshot=cast(#{outcome} as jsonb)
 where study_id=#{studyId} and sample_type=#{sampleType} and stock_code=#{code} and market=#{market}
   and event_trade_date=#{eventTradeDate}

update cynexus_appl_market.market_factor_study_sample samples set outcome_snapshot=cast(values_row.outcome as jsonb) from (values
(#{outcome.sampleType}, #{outcome.code}, #{outcome.market}, #{outcome.eventTradeDate}, #{outcome.outcome})
) as values_row(sample_type, stock_code, market, event_trade_date, outcome) where samples.study_id=#{studyId} and samples.sample_type=values_row.sample_type and samples.stock_code=values_row.stock_code and samples.market=values_row.market and samples.event_trade_date=values_row.event_trade_date

update cynexus_appl_market.market_factor_study_factor_result results
   set verdict='PROMOTED'
  from cynexus_appl_market.market_factor_study studies
 where results.study_id=studies.id and studies.tenant_id=#{tenantId} and studies.owner_id=#{ownerId}
   and studies.study_code=#{studyCode} and results.discovery_code=#{discoveryCode}
   and results.verdict='CANDIDATE'
